SELECT MAX(t.updated_at)
FROM (SELECT updated_at FROM site_legend_material_states WHERE user_id = #{userId}
      UNION ALL
      SELECT updated_at FROM site_legend_states WHERE user_id = #{userId}
      UNION ALL
      SELECT updated_at FROM site_legend_preferences WHERE user_id = #{userId}) t

